from pathlib import Path
import json, shutil

ROOT=Path('/mnt/data/raildock-web')
DOCS=ROOT/'docs'
DOCS.mkdir(exist_ok=True)

package={
  "name":"raildock-docs","private":True,"version":"0.1.0","type":"module",
  "scripts":{"dev":"vite --host 0.0.0.0","build":"vite build","preview":"vite preview --host 0.0.0.0"},
  "dependencies":{"@holocron.so/vite":"0.32.0","react":"^19.2.0","react-dom":"^19.2.0","vite":"^7.2.4"}
}
(DOCS/'package.json').write_text(json.dumps(package,indent=2)+"\n")
